// 排序 + 雙指標
// 時間複雜度: O(n²)，空間複雜度: O(log n)（排序）
function threeSum(nums) {
    nums.sort((a, b) => a - b);
    const result = [];
    const n = nums.length;
    for (let i = 0; i < n - 2; i++) {
        if (nums[i] > 0)
            break; // 最小值已大於 0，不可能湊出 0
        if (i > 0 && nums[i] === nums[i - 1])
            continue; // 跳過重複的第一個數
        let left = i + 1, right = n - 1;
        while (left < right) {
            const sum = nums[i] + nums[left] + nums[right];
            if (sum === 0) {
                result.push([nums[i], nums[left], nums[right]]);
                while (left < right && nums[left] === nums[left + 1])
                    left++;
                while (left < right && nums[right] === nums[right - 1])
                    right--;
                left++;
                right--;
            }
            else if (sum < 0) {
                left++;
            }
            else {
                right--;
            }
        }
    }
    return result;
}

