#include <vector>
#include <algorithm>

class Solution {
public:
    /**
     * 排序 + 雙指標
     * 時間複雜度: O(n²)
     * 空間複雜度: O(log n) 到 O(n)
     */
    std::vector<std::vector<int>> threeSum(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        std::vector<std::vector<int>> result;
        int n = nums.size();

        for (int i = 0; i < n - 2; i++) {
            // 如果第一個數已經大於 0，後面不可能找到和為 0 的三元組
            if (nums[i] > 0) {
                break;
            }

            // 跳過重複的第一個數
            if (i > 0 && nums[i] == nums[i-1]) {
                continue;
            }

            // 雙指標找另外兩個數
            int left = i + 1, right = n - 1;

            while (left < right) {
                int total = nums[i] + nums[left] + nums[right];

                if (total == 0) {
                    // 找到一個解
                    result.push_back({nums[i], nums[left], nums[right]});

                    // 跳過重複的第二個數
                    while (left < right && nums[left] == nums[left + 1]) {
                        left++;
                    }
                    // 跳過重複的第三個數
                    while (left < right && nums[right] == nums[right - 1]) {
                        right--;
                    }

                    // 移動指標繼續尋找
                    left++;
                    right--;

                } else if (total < 0) {
                    // 和太小，需要更大的數
                    left++;
                } else {
                    // 和太大，需要更小的數
                    right--;
                }
            }
        }

        return result;
    }
};

