// 排序 + 雙指標
// 時間複雜度: O(n²)，空間複雜度: O(log n)（不含輸出）
static int cmp(const void* a, const void* b) {
    int x = *(const int*)a, y = *(const int*)b;
    return (x > y) - (x < y);
}

int** threeSum(int* nums, int numsSize, int* returnSize, int** returnColumnSizes) {
    qsort(nums, numsSize, sizeof(int), cmp);
    int cap = 64;
    int** result = malloc(sizeof(int*) * cap);
    *returnColumnSizes = malloc(sizeof(int) * cap);
    *returnSize = 0;

    for (int i = 0; i < numsSize - 2; i++) {
        if (nums[i] > 0) break;
        if (i > 0 && nums[i] == nums[i - 1]) continue;   // 跳過重複

        int left = i + 1, right = numsSize - 1;
        while (left < right) {
            int sum = nums[i] + nums[left] + nums[right];
            if (sum == 0) {
                if (*returnSize == cap) {                // 空間不足時擴容
                    cap *= 2;
                    result = realloc(result, sizeof(int*) * cap);
                    *returnColumnSizes = realloc(*returnColumnSizes, sizeof(int) * cap);
                }
                int* triple = malloc(sizeof(int) * 3);
                triple[0] = nums[i]; triple[1] = nums[left]; triple[2] = nums[right];
                (*returnColumnSizes)[*returnSize] = 3;
                result[(*returnSize)++] = triple;
                while (left < right && nums[left] == nums[left + 1]) left++;
                while (left < right && nums[right] == nums[right - 1]) right--;
                left++;
                right--;
            } else if (sum < 0) {
                left++;
            } else {
                right--;
            }
        }
    }
    return result;
}

